const docPut=(ns,id,u)=>DBX.run('readwrite',s=>s.put(u,ns+'|'+id)),docGet=(ns,id)=>DBX.run('readonly',s=>s.get(ns+'|'+id)),docRm=(ns,id)=>DBX.run('readwrite',s=>s.delete(ns+'|'+id)),docRmNs=ns=>DBX.run('readwrite',s=>s.delete(IDBKeyRange.bound(ns+'|',ns+'|\uffff')));
