const u2b=u=>{const m=String(u).match(/^data:([^;,]*)(;base64)?,/);if(!m)return null;const raw=String(u).slice(m[0].length),b=m[2]?atob(raw):decodeURIComponent(raw),a=new Uint8Array(b.length);for(let i=0;i<b.length;i++)a[i]=b.charCodeAt(i);return {a,ty:m[1]||''}};
/* only images and PDFs open in a tab; anything else is downloaded, never rendered (a client file is not trusted content) */
const docOpen=(id,dlOnly)=>{const d=(S.docs||[]).find(x=>x.id==id);if(!d)return;const view=/\.(png|jpe?g|webp|gif|pdf)$/i.test(d.n)&&!dlOnly,w=view?window.open('about:blank','_blank'):null;docGet(K,id).then(u=>{const b=u&&u2b(u);if(!b){if(w)w.close();say('That file is not stored in this browser.'+(CVID?' The client sent the file without documents.':''));return}const ok=/^(image\/(png|jpeg|webp|gif)|application\/pdf)$/.test(b.ty);if(w&&ok){w.location.href=URL.createObjectURL(new Blob([b.a],{type:b.ty}))}else{if(w)w.close();const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([b.a],{type:'application/octet-stream'}));a.download=d.n||'document';a.click()}}).catch(()=>{if(w)w.close();say('Could not read that file from this browser.')})};
