const pBak=async()=>{const pw=await askP('Passcode to lock the backup file (recommended).\nLeave blank for no passcode.','passcode','Download');if(pw==null)return;if(pw&&!hasSub()){say('This browser cannot lock files with a passcode here. Leave it blank, or open the portal over https.');return}const cl={};S.cpa.cl.forEach(c=>{try{cl[c.id]=localStorage.getItem(cKey(c.id))}catch(e){}});const o={repstr:1,kind:'portal',v:1,ts:Date.now(),cpa:S.cpa,cl},out=pw?{repstr:1,kind:'portal',v:1,enc:await encJ(JSON.stringify(o),pw)}:o;dl('REPSTR-portal-backup-'+today()+'.json',JSON.stringify(out),'application/json')};
